ALTER POLICY "Users can delete their own stock items" ON public.stock_items USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can update their own stock items" ON public.stock_items USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL))) WITH CHECK(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can insert their own stock items" ON public.stock_items WITH CHECK(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can view their own stock items" ON public.stock_items USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can delete their own custom boxes" ON public.custom_boxes USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can update their own custom boxes" ON public.custom_boxes USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL))) WITH CHECK(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can insert their own custom boxes" ON public.custom_boxes WITH CHECK(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can view their own custom boxes" ON public.custom_boxes USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
ALTER POLICY "Users can view their own usage history" ON public.usage_history USING(auth.uid()=user_id AND (vessel_id=public.current_vessel() OR (vessel_id IS NULL AND public.current_vessel() IS NULL)));
REVOKE INSERT ON public.usage_history FROM authenticated,anon;
CREATE INDEX stock_vessel_idx ON public.stock_items(vessel_id);
CREATE INDEX boxes_vessel_idx ON public.custom_boxes(vessel_id);
CREATE INDEX history_vessel_idx ON public.usage_history(vessel_id);
CREATE INDEX tasks_vessel_idx ON public.tasks(vessel_id);
CREATE TABLE public.deck_orders (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vessel_id uuid NOT NULL DEFAULT public.current_vessel() REFERENCES public.vessels(id), product_name text NOT NULL, quantity text NOT NULL DEFAULT '', colour text NOT NULL DEFAULT '', size text NOT NULL DEFAULT '', link text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.deck_orders TO authenticated; GRANT ALL ON public.deck_orders TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.deck_orders_id_seq TO authenticated,service_role;
ALTER TABLE public.deck_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY deck_orders_access ON public.deck_orders FOR ALL TO authenticated USING(vessel_id=public.current_vessel()) WITH CHECK(vessel_id=public.current_vessel());
ALTER PUBLICATION supabase_realtime ADD TABLE public.deck_orders;
CREATE INDEX orders_vessel_idx ON public.deck_orders(vessel_id);